select coalesce(json_agg(json_build_object('table',c.relname,'grantee',case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,'privilege',x.privilege_type,'grantable',x.is_grantable) order by c.relname,2,3),'[]'::json) as data from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(c.relacl) x where n.nspname='public' and c.relkind in ('r','p','v','m','S');
